import{_ as a,o as s,c as o,ag as r,j as n}from"./chunks/framework.KxDd3USm.js";const x=JSON.parse('{"title":"06.1 网络分层模型 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"06-计算机网络/01-网络分层模型.md","filePath":"06-计算机网络/01-网络分层模型.md"}'),d={name:"06-计算机网络/01-网络分层模型.md"},e={class:"fig"},g={"data-figure-id":"figure-26",viewBox:"0 0 720 350",width:"100%",style:{"max-width":"720px"},role:"img","aria-label":"发送端的封装过程。应用数据先加 TCP 或 UDP 首部成为段或数据报；再加 IP 首部成为分组；最后加帧首部和帧尾成为帧，并编码为比特流。接收端按相反方向逐层拆除各自首尾。"};function i(l,t,h,p,P,u){return s(),o("div",null,[t[2]||(t[2]=r(`<h1 id="_06-1-网络分层模型-★★★" tabindex="-1">06.1 网络分层模型 ★★★ <a class="header-anchor" href="#_06-1-网络分层模型-★★★" aria-label="Permalink to &quot;06.1 网络分层模型 ★★★&quot;">​</a></h1><h3 id="为什么要分层" tabindex="-1">为什么要分层 <a class="header-anchor" href="#为什么要分层" aria-label="Permalink to &quot;为什么要分层&quot;">​</a></h3><p>网络通信是一个庞大的问题：比特怎么变成电信号、相邻设备怎么传数据、跨网络的两个程序怎么可靠对话……一口气解决无从下手。于是把整个通信过程<strong>按职责切成若干层</strong>，每层只干一类事、只跟上下层打交道——这和软件工程里&quot;模块化、高内聚低耦合&quot;是同一个思想（见 <a href="/ruankao/03-软件工程基础/03-模块化设计.html">03-软件工程基础.md</a> 第三节）：<strong>层次 = 模块，层间接口 = 模块接口</strong>。分层的直接好处：各层独立演进、出问题可以定位到层、不同厂商设备按同一分层标准互通。</p><h3 id="osi-七层模型-必背顺序与职责" tabindex="-1">OSI 七层模型（必背顺序与职责） <a class="header-anchor" href="#osi-七层模型-必背顺序与职责" aria-label="Permalink to &quot;OSI 七层模型（必背顺序与职责）&quot;">​</a></h3><p>OSI 是国际标准化组织提出的<strong>理论参考模型</strong>，从下往上共 7 层。考试最爱考：<strong>层名顺序、每层干什么、每层的协议、每层的设备</strong>。</p><table tabindex="0"><thead><tr><th>层号</th><th>层名</th><th>职责（一句话）</th><th>数据单位（PDU）</th><th>代表协议</th><th>代表设备</th></tr></thead><tbody><tr><td>7</td><td><strong>应用层</strong></td><td>直接为用户程序提供服务</td><td>数据 / 报文</td><td>HTTP、FTP、SMTP、DNS、DHCP</td><td>网关</td></tr><tr><td>6</td><td><strong>表示层</strong></td><td>数据格式转换：<strong>加密/解密、压缩/解压、编码转换</strong></td><td>数据 / 报文</td><td>—</td><td>—</td></tr><tr><td>5</td><td><strong>会话层</strong></td><td>建立、管理、终止会话（对话的&quot;开场与散会&quot;）</td><td>数据 / 报文</td><td>—</td><td>—</td></tr><tr><td>4</td><td><strong>传输层</strong></td><td><strong>端到端</strong>可靠/不可靠传输，用<strong>端口号</strong>区分应用</td><td>TCP <strong>段</strong> / UDP <strong>数据报</strong></td><td><strong>TCP、UDP</strong></td><td>—</td></tr><tr><td>3</td><td><strong>网络层</strong></td><td><strong>寻址与路由</strong>（按 IP 地址选路径），跨网转发</td><td><strong>分组（包、IP 数据报）</strong></td><td><strong>IP、ICMP、ARP</strong></td><td><strong>路由器</strong></td></tr><tr><td>2</td><td><strong>数据链路层</strong></td><td>相邻节点间成帧、差错控制、按 <strong>MAC 地址</strong>转发</td><td><strong>帧</strong></td><td>以太网协议、PPP</td><td><strong>网桥、交换机</strong></td></tr><tr><td>1</td><td><strong>物理层</strong></td><td>比特流变成电/光信号在介质上传输</td><td><strong>比特</strong></td><td>—</td><td><strong>中继器、集线器</strong></td></tr></tbody></table><p><strong>层名口诀</strong>：从下往上——<strong>物数网传会表应</strong>（联想：&quot;悟数网，传会表应&quot;：先悟出数据的网络传输，再&quot;会上表应&quot;——开会、表演、回应，从下到上越来越&quot;面向应用&quot;）。</p><p><strong>记层职责的抓手</strong>：物理层管&quot;信号&quot;，链路层管&quot;相邻两站&quot;（MAC），网络层管&quot;全程寻路&quot;（IP），传输层管&quot;程序到程序&quot;（端口），会话/表示/应用三层合起来管&quot;应用怎么说话&quot;。</p><h3 id="pdu-与封装-同一份数据为什么一路改名字-★★" tabindex="-1">PDU 与封装：同一份数据为什么一路改名字 ★★ <a class="header-anchor" href="#pdu-与封装-同一份数据为什么一路改名字-★★" aria-label="Permalink to &quot;PDU 与封装：同一份数据为什么一路改名字 ★★&quot;">​</a></h3><p><strong>PDU</strong>（Protocol Data Unit，协议数据单元）就是“某一层眼里的完整数据”。发送时，每层都把上层交下来的内容当作自己的“货物”，再加上本层控制信息；因此同一份网页数据会随着下行不断换包装、换名字：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>应用数据</span></span>
<span class="line"><span>  ↓ 加 TCP/UDP 首部（源/目的端口等）</span></span>
<span class="line"><span>TCP 段 / UDP 数据报</span></span>
<span class="line"><span>  ↓ 加 IP 首部（源/目的 IP 等）</span></span>
<span class="line"><span>IP 分组（包）</span></span>
<span class="line"><span>  ↓ 加帧首部和帧尾（源/目的 MAC、差错检测等）</span></span>
<span class="line"><span>数据帧</span></span>
<span class="line"><span>  ↓ 编码成信号</span></span>
<span class="line"><span>比特流</span></span></code></pre></div>`,11)),n("figure",e,[(s(),o("svg",g,[...t[0]||(t[0]=[r('<defs><marker id="net-arrow" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8z" fill="var(--ink)"></path></marker></defs><text x="36" y="30" class="t">发送端：向下逐层加包装</text><text x="450" y="30" class="t">接收端：向上逐层解封装</text><rect x="160" y="52" width="190" height="40" class="data"></rect><text x="225" y="77" class="t">应用数据</text><path d="M255 93V113" stroke="var(--ink)" stroke-width="2" marker-end="url(#net-arrow)"></path><rect x="125" y="116" width="55" height="40" class="head"></rect><rect x="180" y="116" width="170" height="40" class="data"></rect><text x="136" y="141" class="s">TCP/UDP</text><text x="225" y="141" class="t">段 / 数据报</text><path d="M255 157V177" stroke="var(--ink)" stroke-width="2" marker-end="url(#net-arrow)"></path><rect x="92" y="180" width="55" height="40" class="ip"></rect><rect x="147" y="180" width="203" height="40" class="data"></rect><text x="108" y="205" class="s">IP</text><text x="222" y="205" class="t">分组（包）</text><path d="M255 221V241" stroke="var(--ink)" stroke-width="2" marker-end="url(#net-arrow)"></path><rect x="58" y="244" width="55" height="40" class="head"></rect><rect x="113" y="244" width="237" height="40" class="data"></rect><rect x="350" y="244" width="42" height="40" class="head"></rect><text x="63" y="269" class="s">帧首</text><text x="214" y="269" class="t">帧</text><text x="354" y="269" class="s">帧尾</text><path d="M255 285V305" stroke="var(--ink)" stroke-width="2" marker-end="url(#net-arrow)"></path><text x="229" y="332" class="t">比特流</text><path d="M480 300V74" stroke="var(--ink)" stroke-width="2" marker-end="url(#net-arrow)"></path><text x="495" y="180" class="s">反向逐层拆除本层首尾</text>',26)])])),t[1]||(t[1]=n("figcaption",null,"MAC 服务“下一跳”、IP 服务“最终主机”、端口服务“最终程序”，所以它们要分层封装。",-1))]),t[3]||(t[3]=r('<p>接收方按相反方向逐层<strong>解封装</strong>：比特 → 帧 → 分组 → 段/数据报 → 应用数据。每层只检查并拆掉自己的包装，再把里面的内容交给上一层。</p><p><strong>为什么不能只加一个总首部？</strong> 因为各层解决的问题不同：链路层的 MAC 负责“这一跳交给谁”，网络层的 IP 负责“最终主机在哪里”，传输层的端口负责“最终交给哪个程序”。把职责分开后，更换局域网技术时不必改应用程序。</p><p><strong>反例演示</strong>：</p><ol><li>“数据链路层的数据单位是分组”——错。链路层是<strong>帧</strong>，网络层才是分组；看到交换机、MAC 就联想到帧。</li><li>“路由器转发时，源和目的 IP 每一跳都要改”——通常错。普通路由转发中端到端的源/目的 IP 保持不变，但帧的源/目的 MAC 会随下一跳重写；经过 NAT 时 IP/端口才可能被转换。</li></ol><p><strong>应试动作</strong>：把“<strong>比特—帧—分组—段—数据</strong>”按物理层到应用层背熟；题干出现“封装顺序”就按发送方向从上往下写，出现“解封装”就反过来。</p><h3 id="tcp-ip-四层模型-实际在用的模型" tabindex="-1">TCP/IP 四层模型（实际在用的模型） <a class="header-anchor" href="#tcp-ip-四层模型-实际在用的模型" aria-label="Permalink to &quot;TCP/IP 四层模型（实际在用的模型）&quot;">​</a></h3><p>互联网实际采用 TCP/IP 四层模型，它与 OSI 的对应关系<strong>每年可能考一题</strong>，必须能画出来：</p><table tabindex="0"><thead><tr><th>TCP/IP 四层</th><th>对应 OSI 的层</th><th>协议举例</th></tr></thead><tbody><tr><td><strong>应用层</strong></td><td>应用 + 表示 + 会话（三层合一）</td><td>HTTP、FTP、SMTP、DNS、DHCP、TELNET</td></tr><tr><td><strong>传输层</strong></td><td>传输层</td><td>TCP、UDP</td></tr><tr><td><strong>网际层（网络层）</strong></td><td>网络层</td><td>IP、ICMP、ARP</td></tr><tr><td><strong>网络接口层</strong></td><td>数据链路层 + 物理层</td><td>以太网、PPP</td></tr></tbody></table><p><strong>判断口诀</strong>：看到 TCP/UDP → 传输层；看到 IP/ICMP/ARP → 网际层；其余有名有姓的&quot;应用协议&quot;（HTTP、FTP、SMTP、DNS、DHCP、TELNET……）→ 应用层。OSI 里的表示层功能（加密压缩）在 TCP/IP 里归入应用层实现。</p><h3 id="各层设备与-两个域-高频辨析" tabindex="-1">各层设备与&quot;两个域&quot;（高频辨析） <a class="header-anchor" href="#各层设备与-两个域-高频辨析" aria-label="Permalink to &quot;各层设备与&quot;两个域&quot;（高频辨析）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设备</th><th>工作层次</th><th>能否隔离冲突域</th><th>能否隔离广播域</th></tr></thead><tbody><tr><td><strong>集线器（Hub）</strong></td><td>物理层</td><td><strong>不能</strong>（所有端口共享一条&quot;路&quot;，一起抢）</td><td>不能</td></tr><tr><td><strong>交换机（二层）</strong></td><td>数据链路层</td><td><strong>能</strong>（每个端口一个冲突域）</td><td><strong>不能</strong>（默认全网一个广播域）</td></tr><tr><td><strong>路由器</strong></td><td>网络层</td><td>能</td><td><strong>能</strong>（广播到路由器就被拦下）</td></tr></tbody></table><ul><li><strong>冲突域</strong>：多个设备同时发信号会&quot;撞车&quot;的范围。集线器把大家拴在一条路上，撞车照旧；交换机每个端口独享带宽，撞车只可能发生在&quot;一条线一个设备&quot;内部（即不存在）。</li><li><strong>广播域</strong>：一个广播帧能扩散到的范围。交换机收到广播帧会<strong>转发给所有其他端口</strong>（广播域不变大也不变小），路由器收到广播帧<strong>不转发</strong>（广播域被切断了）。</li></ul><p><strong>反例演示</strong>：</p><ol><li>&quot;交换机隔离广播域&quot;——<strong>错</strong>。交换机只隔离冲突域；要隔离广播域得上路由器（或划 VLAN）。</li><li>&quot;集线器工作在数据链路层&quot;——<strong>错</strong>。集线器只认识电信号、不认识 MAC 地址，是纯物理层设备。</li><li>&quot;路由器根据 MAC 地址转发&quot;——<strong>错</strong>。路由器根据 <strong>IP 地址</strong>（第三层地址）查路由表转发；按 MAC 转发的是交换机。</li></ol><p><strong>应试动作</strong>：① 七层顺序与四层对应关系背死，考法是&quot;XX 协议/设备属于哪一层&quot;的秒答题；② 设备三件套对应（集线器—物理层、交换机—链路层、路由器—网络层）加&quot;两个域&quot;的隔离能力表；③ 判断依据记牢：按 MAC 转发=链路层，按 IP 转发=网络层，按端口交付进程=传输层。</p>',15))])}const q=a(d,[["render",i]]);export{x as __pageData,q as default};
